WITH said AS (SELECT DISTINCT lower(replace(x[1], '.md', '')) AS n, min(f.name) AS где FROM code_fact f CROSS JOIN LATERAL regexp_matches(f.detail, '([A-Za-z0-9_.-]+)[.]md', 'g') AS x WHERE f.project_id = $1 AND f.kind = 'doc-name-in-code' GROUP BY 1) SELECT 'датчик «doc-name-in-code» ' || fact_gap($1, 'doc-name-in-code') || ': проверить нечем, и это не зелёное' AS detail WHERE NOT fact_fresh($1, 'doc-name-in-code') UNION ALL SELECT said.n || '.md — код называет документ, а в наборе такого нет (' || said.где || ')' AS detail FROM said WHERE NOT EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = $1 AND (lower(d.entity_name) = said.n OR lower(d.entity_name) LIKE '%/' || said.n OR (d.entity_name = '' AND lower(d.entity_kind) = said.n) OR (d.entity_kind = 'decision' AND lower(d.entity_name) = 'adr-' || substring(said.n from '^([0-9]{4})')))) AND true ORDER BY 1
